// CriteriaFilterPanel.js
import React from 'react';
import Slider from '@mui/material/Slider';

const CriteriaFilterPanel = ({ criteria, setCriteria }) => {
  const handleSliderChange = (name, value) => {
    setCriteria((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  return (
    <div>
      <h3>Filter Criteria</h3>

      <div>
        <label>Tempo Range</label>
        <Slider
          value={criteria.tempoRange || [0, 200]}
          onChange={(e, newValue) => handleSliderChange('tempoRange', newValue)}
          valueLabelDisplay="auto"
          min={0}
          max={200}
        />
      </div>

      <div>
        <label>Danceability Range</label>
        <Slider
          value={criteria.danceabilityRange || [0, 1]}
          onChange={(e, newValue) => handleSliderChange('danceabilityRange', newValue)}
          valueLabelDisplay="auto"
          min={0}
          max={1}
          step={0.01}
        />
      </div>

      {/* Repeat similar sliders for energy, valence, acousticness, etc. */}
    </div>
  );
};

export default CriteriaFilterPanel;
